      figure: "<svg viewBox=\"0 0 420 330\" width=\"100%\" style=\"max-width:420px;height:auto\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"ah-2022-cs40\" markerWidth=\"7\" markerHeight=\"7\" refX=\"6\" refY=\"3.5\" orient=\"auto\"><path d=\"M0,0 L7,3.5 L0,7 Z\" fill=\"currentColor\"/></marker></defs><text x=\"150\" y=\"14\" font-size=\"12\" fill=\"currentColor\">Code Word</text><rect x=\"20\" y=\"24\" width=\"50\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"35\" y=\"41\" font-size=\"12\" fill=\"currentColor\">M</text><rect x=\"70\" y=\"24\" width=\"140\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"88\" y=\"41\" font-size=\"12\" fill=\"currentColor\">S-address</text><rect x=\"210\" y=\"24\" width=\"140\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"238\" y=\"41\" font-size=\"12\" fill=\"currentColor\">R-address</text><line x1=\"140\" y1=\"50\" x2=\"140\" y2=\"84\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"110\" y=\"84\" width=\"60\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"135\" y=\"101\" font-size=\"12\" fill=\"currentColor\">P</text><line x1=\"280\" y1=\"50\" x2=\"280\" y2=\"84\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"250\" y=\"84\" width=\"60\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"275\" y=\"101\" font-size=\"12\" fill=\"currentColor\">Q</text><line x1=\"140\" y1=\"110\" x2=\"140\" y2=\"154\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"115\" y=\"154\" width=\"50\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"132\" y=\"171\" font-size=\"12\" fill=\"currentColor\">S</text><line x1=\"280\" y1=\"110\" x2=\"280\" y2=\"154\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"255\" y=\"154\" width=\"50\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"272\" y=\"171\" font-size=\"12\" fill=\"currentColor\">R</text><line x1=\"140\" y1=\"180\" x2=\"200\" y2=\"214\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><line x1=\"280\" y1=\"180\" x2=\"220\" y2=\"214\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><line x1=\"45\" y1=\"50\" x2=\"45\" y2=\"227\" stroke=\"currentColor\"/><line x1=\"45\" y1=\"227\" x2=\"180\" y2=\"227\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"180\" y=\"214\" width=\"70\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"200\" y=\"231\" font-size=\"12\" fill=\"currentColor\">T</text><line x1=\"215\" y1=\"240\" x2=\"215\" y2=\"274\" stroke=\"currentColor\" marker-end=\"url(#ah-2022-cs40)\"/><rect x=\"170\" y=\"274\" width=\"50\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"188\" y=\"291\" font-size=\"12\" fill=\"currentColor\">X</text><rect x=\"220\" y=\"274\" width=\"70\" height=\"26\" fill=\"none\" stroke=\"currentColor\"/><text x=\"233\" y=\"291\" font-size=\"12\" fill=\"currentColor\">DDS</text></svg>",
      options: ["P is 10:1 multiplexer; Q is 5:1 multiplexer; T is 2:1 multiplexer","P is 10:2^10 decoder; Q is 5:2^5 decoder; T is 2:1 encoder","P is 10:2^10 decoder; Q is 5:2^5 decoder; T is 2:1 multiplexer","P is 1:10 de-multiplexer; Q is 1:5 de-multiplexer; T is 2:1 multiplexer"],
